INSERT INTO quantity_kinds (name, default_unit, dimension, description) VALUES
    ('ActivePower', 'MW', '{"L":2,"M":1,"T":-3}', 'Active (real) power'),
    ('ActivePowerChangeRate', 'MW/min', '{"L":2,"M":1,"T":-4}', 'Rate of change of active power (ramp)'),
    ('Angle', 'rad', '{}', 'Angle (allowed units rad and deg)'),
    ('ApparentPower', 'MVA', '{"L":2,"M":1,"T":-3}', 'Apparent power'),
    ('CO2Emissions', 't/MMBtu', '{"Btu":-1,"M":1}', 'CO2 emission rate (mass per unit of fuel energy)'),
    ('CalendarPeriod', 'yr', '{"T":1}', 'Long-term planning span, a whole number of years. Integer-valued. Deliberately carries no to_default bridge into Duration or OperationalDuration: a calendar year is not a fixed number of seconds, so any such factor would silently bake in a 365-day convention. ''ucum'' is null for the same reason: every UCUM year atom is longer than 365 days (a/a_j = 365.25, a_g = 365.2425, a_t = 365.24219), so none of them matches the 365-day year this vocabulary actually uses. Emitting "a" would hand a consumer a leap-day convention we do not follow.'),
    ('Capacitance', 'F', '{"I":2,"L":-2,"M":-1,"T":4}', 'Capacitance'),
    ('Conductance', 'S', '{"I":2,"L":-2,"M":-1,"T":3}', 'Conductance'),
    ('CostPerCapacity', 'USD/MW', '{"L":-2,"M":-1,"T":3,"USD":1}', 'Cost per unit of capacity (capital cost)'),
    ('CostPerEnergy', 'USD/MWh', '{"L":-2,"M":-1,"T":2,"USD":1}', 'Cost per unit of energy (operation / energy capital cost)'),
    ('CostPerLevel', 'USD/m', '{"L":-1,"USD":1}', 'Cost per unit of hydraulic head (e.g. reservoir operation cost when level_data_type=HEAD)'),
    ('CostPerMass', 'USD/t', '{"M":-1,"USD":1}', 'Cost per unit of mass (e.g. carbon price or tax)'),
    ('CostPerTime', 'USD/h', '{"T":-1,"USD":1}', 'Cost per unit of time'),
    ('CostPerVolume', 'USD/m3', '{"L":-3,"USD":1}', 'Cost per unit of volume (e.g. reservoir operation cost)'),
    ('CurrentFlow', 'kA', '{"I":1}', 'Current flow'),
    ('Dimensionless', '1', '{}', 'Dimensionless quantity'),
    ('Duration', 's', '{"T":1}', 'Continuous-time duration or time constant, real-valued seconds. Dynamics time constants are inherently fractional, so no integer representation exists for them. Discrete scheduling durations use OperationalDuration; multi-year planning spans use CalendarPeriod.'),
    ('ElectricalEnergy', 'MWh', '{"L":2,"M":1,"T":-2}', 'Real (electrical) energy'),
    ('Elevation', 'm', '{"L":1}', 'Elevation / hydraulic head'),
    ('EmissionRate', 't/MWh', '{"L":-2,"T":2}', 'Emission mass per unit of electrical energy'),
    ('Fraction', '1', '{}', 'Fractional quantity (efficiency, losses, cofire level, etc.)'),
    ('FractionPerTime', '1/min', '{"T":-1}', 'A fraction of a stored quantity lost or decayed per unit of time (storage self-discharge, leakage). Per minute, matching OperationalDuration: the value multiplies the simulation step, so its time basis must be the same one durations use or the decay is wrong by the ratio of the two. Distinct from Frequency despite sharing the T^-1 dimension.'),
    ('Frequency', 'Hz', '{"T":-1}', 'Frequency'),
    ('HeadRate', 'm/s', '{"L":1,"T":-1}', 'Rate of change of hydraulic head'),
    ('HeatRate', 'MMBtu/MWh', '{"Btu":1,"L":-2,"M":-1,"T":2}', 'Heat rate (fuel energy per unit of electrical energy)'),
    ('Impedance', 'ohm', '{"I":-2,"L":2,"M":1,"T":-3}', 'Impedance'),
    ('Inductance', 'H', '{"I":-2,"L":2,"M":1,"T":-2}', 'Inductance'),
    ('Length', 'km', '{"L":1}', 'Length'),
    ('Mass', 't', '{"M":1}', 'Mass'),
    ('Money', 'USD', '{"USD":1}', 'Monetary value'),
    ('OperationalDuration', 'min', '{"T":1}', 'Operational or scheduling duration, expressed in minutes. The unit is the convention; integrality is not. Most of these fields are real-valued because the data model library validates them on an open (0, nothing) range and sub-minute products are legitimate (a 30-second reserve, a fractional-minute saturation window). Declare a field integer only where the domain is genuinely discrete and the ingest path rounds -- no current field qualifies. Sub-minute control timing belongs in Duration instead.'),
    ('PowerFactor', '1', '{}', 'Power factor'),
    ('PowerPerFrequency', 'MW/Hz', '{"L":2,"M":1,"T":-2}', 'Active power response per unit of frequency deviation (regulation / droop participation)'),
    ('Reactance', 'ohm', '{"I":-2,"L":2,"M":1,"T":-3}', 'Reactance'),
    ('ReactivePower', 'MVAr', '{"L":2,"M":1,"T":-3}', 'Reactive power'),
    ('Resistance', 'ohm', '{"I":-2,"L":2,"M":1,"T":-3}', 'Resistance'),
    ('StartFuelPerCapacity', 'MMBtu/MW', '{"Btu":1,"L":-2,"M":-1,"T":3}', 'Start-up fuel per unit of capacity'),
    ('Susceptance', 'S', '{"I":2,"L":-2,"M":-1,"T":3}', 'Susceptance'),
    ('Voltage', 'kV', '{"I":-1,"L":2,"M":1,"T":-3}', 'Voltage'),
    ('VoltagePerPower', 'kV/MW', '{"I":-1}', 'Voltage change per unit of active power (DC voltage droop gain)'),
    ('Volume', 'm3', '{"L":3}', 'Volume'),
    ('VolumeFlowRate', 'm3/s', '{"L":3,"T":-1}', 'Volumetric flow rate');
