INSERT INTO unit_conventions (table_name, column_name, quantity_kind, unit, discriminator_column, discriminator_value, discriminator_column_2, discriminator_value_2, base_power_ref, base_voltage_ref, description) VALUES
    ('attributes', 'ac_voltage_setpoint_from', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'AC-side voltage magnitude target of the `from` bus converter, used when `ac_control_from` is `AC_VOLTAGE`; `null` otherwise.'),
    ('attributes', 'ac_voltage_setpoint_to', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'AC-side voltage magnitude target of the `to` bus converter, used when `ac_control_to` is `AC_VOLTAGE`; `null` otherwise.'),
    ('attributes', 'active_power', 'ActivePower', 'MW', NULL, NULL, NULL, NULL, NULL, NULL, 'Active power setpoint'),
    ('attributes', 'active_power_flow', 'ActivePower', 'MW', NULL, NULL, NULL, NULL, NULL, NULL, 'Branch active power flow'),
    ('attributes', 'active_power_limits', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Minimum and maximum stable active power levels.'),
    ('attributes', 'active_power_limits', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Minimum and maximum stable active power levels.'),
    ('attributes', 'active_power_limits_pump', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Minimum and maximum stable active power levels for the pump.'),
    ('attributes', 'active_power_limits_pump', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Minimum and maximum stable active power levels for the pump.'),
    ('attributes', 'active_power_pump', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Initial active power set point of the pump unit. For power flow, this is the steady state operating point of the system. For production cost modeling, this may or may not be used as the initial starting point for the solver, depending on the solver used.'),
    ('attributes', 'active_power_pump', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Initial active power set point of the pump unit. For power flow, this is the steady state operating point of the system. For production cost modeling, this may or may not be used as the initial starting point for the solver, depending on the solver used.'),
    ('attributes', 'alpha', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Exponent relating voltage dependency for active power. 0 = constant power only, 1 = constant current only, and 2 = constant impedance only.'),
    ('attributes', 'angle', 'Angle', 'rad', NULL, NULL, NULL, NULL, NULL, NULL, 'Bus voltage angle'),
    ('attributes', 'angle_limits', 'Angle', 'rad', NULL, NULL, NULL, NULL, NULL, NULL, 'Branch phase-angle-difference limits'),
    ('attributes', 'base_power', 'ApparentPower', 'MVA', NULL, NULL, NULL, NULL, NULL, NULL, 'System base power for per-unitization of this component''s per-unit fields, recorded per component in lieu of a system-level table.'),
    ('attributes', 'base_voltage', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'Bus base voltage'),
    ('attributes', 'beta', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Exponent relating voltage dependency for reactive power. 0 = constant power only, 1 = constant current only, and 2 = constant impedance only.'),
    ('attributes', 'capacity_limits', 'ActivePower', 'MW', NULL, NULL, NULL, NULL, NULL, NULL, 'Transport technology capacity band'),
    ('attributes', 'compounding_resistance', 'Resistance', 'ohm', NULL, NULL, NULL, NULL, NULL, NULL, 'Compounding Resistance. This parameter is for control of the DC voltage in the rectifier or inverter end. For inverter DC voltage control, the parameter is set to zero; for rectifier DC voltage control, the parameter is set to the DC line resistance; otherwise, set to a fraction of the DC line resistance.'),
    ('attributes', 'constant_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Constant active power demand (P_P).'),
    ('attributes', 'constant_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Constant active power demand (P_P).'),
    ('attributes', 'constant_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Constant reactive power demand (Q_P).'),
    ('attributes', 'constant_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Constant reactive power demand (Q_P).'),
    ('attributes', 'current_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Active power coefficient for constant current load (P_I).'),
    ('attributes', 'current_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Active power coefficient for constant current load (P_I).'),
    ('attributes', 'current_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Reactive power coefficient for constant current load (Q_I).'),
    ('attributes', 'current_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Reactive power coefficient for constant current load (Q_I).'),
    ('attributes', 'current_transfer_setpoint', 'CurrentFlow', 'A', NULL, NULL, NULL, NULL, NULL, NULL, 'Scheduled current transfer, used when `control_mode` is `CURRENT`; `null` otherwise.'),
    ('attributes', 'dc_current', 'CurrentFlow', 'A', NULL, NULL, NULL, NULL, NULL, NULL, 'DC current on the converter flowing in the DC line, from `from` bus to `to` bus.'),
    ('attributes', 'dc_power_setpoint_from', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Active-power order of the `from` bus converter, used when `dc_control_from` is `DC_POWER`; `null` otherwise. Positive means the converter supplies power to the AC network; negative means it withdraws power from it.'),
    ('attributes', 'dc_power_setpoint_from', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Active-power order of the `from` bus converter, used when `dc_control_from` is `DC_POWER`; `null` otherwise. Positive means the converter supplies power to the AC network; negative means it withdraws power from it.'),
    ('attributes', 'dc_power_setpoint_to', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Active-power order of the `to` bus converter, used when `dc_control_to` is `DC_POWER`; `null` otherwise. Positive means the converter supplies power to the AC network; negative means it withdraws power from it.'),
    ('attributes', 'dc_power_setpoint_to', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Active-power order of the `to` bus converter, used when `dc_control_to` is `DC_POWER`; `null` otherwise. Positive means the converter supplies power to the AC network; negative means it withdraws power from it.'),
    ('attributes', 'dc_voltage_droop', 'VoltagePerPower', 'kV/MW', NULL, NULL, NULL, NULL, NULL, NULL, 'DC-voltage droop gain on the converter, used when `dc_control` is `DC_VOLTAGE_DROOP`: `V_dc = dc_voltage_setpoint - dc_voltage_droop * P_c`, with `V_dc` in kV and `P_c` in MW regardless of `power_units`. A value of 0.0 disables droop.'),
    ('attributes', 'dc_voltage_droop_from', 'VoltagePerPower', 'kV/MW', NULL, NULL, NULL, NULL, NULL, NULL, 'DC-voltage droop gain on the `from` converter, used when `dc_control_from` is `DC_VOLTAGE_DROOP`: `V_dc = dc_voltage_setpoint_from - dc_voltage_droop_from * P_c`, with `V_dc` in kV and `P_c` in MW regardless of `power_units`. A value of 0.0 disables droop.'),
    ('attributes', 'dc_voltage_droop_to', 'VoltagePerPower', 'kV/MW', NULL, NULL, NULL, NULL, NULL, NULL, 'DC-voltage droop gain on the `to` converter, used when `dc_control_to` is `DC_VOLTAGE_DROOP`: `V_dc = dc_voltage_setpoint_to - dc_voltage_droop_to * P_c`, with `V_dc` in kV and `P_c` in MW regardless of `power_units`. A value of 0.0 disables droop.'),
    ('attributes', 'dc_voltage_setpoint_from', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'DC-side voltage target of the `from` bus converter, used when `dc_control_from` is `DC_VOLTAGE` or `DC_VOLTAGE_DROOP`; `null` otherwise.'),
    ('attributes', 'dc_voltage_setpoint_to', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'DC-side voltage target of the `to` bus converter, used when `dc_control_to` is `DC_VOLTAGE` or `DC_VOLTAGE_DROOP`; `null` otherwise.'),
    ('attributes', 'efficiency', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Turbine efficiency [0, 1.0].'),
    ('attributes', 'g', 'Conductance', 'S', NULL, NULL, NULL, NULL, NULL, NULL, 'Series conductance of the DC line.'),
    ('attributes', 'growth_rate', 'Fraction', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'The annual growth rate of the demand requirement, used to scale present-day loads into future projections. Should only be used for conforming loads.'),
    ('attributes', 'impedance_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Active power coefficient for constant impedance load (P_Z).'),
    ('attributes', 'impedance_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Active power coefficient for constant impedance load (P_Z).'),
    ('attributes', 'impedance_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Reactive power coefficient for constant impedance load (Q_Z).'),
    ('attributes', 'impedance_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Reactive power coefficient for constant impedance load (Q_Z).'),
    ('attributes', 'inverter_base_voltage', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter primary base AC voltage, entered in kV.'),
    ('attributes', 'inverter_bridges', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Number of bridges in series in the inverter side.'),
    ('attributes', 'inverter_capacitor_reactance', 'Reactance', 'ohm', NULL, NULL, NULL, NULL, NULL, NULL, 'Commutating inverter capacitor reactance magnitude per bridge.'),
    ('attributes', 'inverter_extinction_angle', 'Angle', 'rad', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter extinction angle (gamma).'),
    ('attributes', 'inverter_extinction_angle_limits', 'Angle', 'rad', NULL, NULL, NULL, NULL, NULL, NULL, 'Minimum and maximum inverter extinction angle (gamma).'),
    ('attributes', 'inverter_rc', 'Resistance', 'ohm', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter commutating transformer resistance per bridge.'),
    ('attributes', 'inverter_tap_limits', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Minimum and maximum inverter tap limits as a ratio between the primary and secondary side AC voltages.'),
    ('attributes', 'inverter_tap_setting', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter transformer tap setting.'),
    ('attributes', 'inverter_tap_step', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter transformer tap step value.'),
    ('attributes', 'inverter_transformer_ratio', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter transformer ratio between the primary and secondary side AC voltages.'),
    ('attributes', 'inverter_xc', 'Reactance', 'ohm', NULL, NULL, NULL, NULL, NULL, NULL, 'Inverter commutating transformer reactance per bridge.'),
    ('attributes', 'load_balance_time_horizon', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Number of time periods over which load must be balanced.'),
    ('attributes', 'load_response', 'PowerPerFrequency', 'MW/Hz', NULL, NULL, NULL, NULL, NULL, NULL, 'Area load-frequency response'),
    ('attributes', 'magnitude', 'Voltage', 'pu', NULL, NULL, NULL, NULL, NULL, NULL, 'Bus voltage magnitude, per-unit on base_voltage'),
    ('attributes', 'max_active_power', 'ActivePower', 'MW', NULL, NULL, NULL, NULL, NULL, NULL, 'Maximum active power demand'),
    ('attributes', 'max_constant_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Maximum active power drawn by constant power load.'),
    ('attributes', 'max_constant_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Maximum active power drawn by constant power load.'),
    ('attributes', 'max_constant_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Maximum reactive power drawn by constant power load.'),
    ('attributes', 'max_constant_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Maximum reactive power drawn by constant power load.'),
    ('attributes', 'max_current_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Maximum active power drawn by constant current load.'),
    ('attributes', 'max_current_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Maximum active power drawn by constant current load.'),
    ('attributes', 'max_current_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Maximum reactive power drawn by constant current load.'),
    ('attributes', 'max_current_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Maximum reactive power drawn by constant current load.'),
    ('attributes', 'max_dc_current', 'CurrentFlow', 'A', NULL, NULL, NULL, NULL, NULL, NULL, 'Maximum stable dc current limits.'),
    ('attributes', 'max_dc_current_from', 'CurrentFlow', 'A', NULL, NULL, NULL, NULL, NULL, NULL, 'Maximum stable dc current limits.'),
    ('attributes', 'max_dc_current_to', 'CurrentFlow', 'A', NULL, NULL, NULL, NULL, NULL, NULL, 'Maximum stable dc current limits.'),
    ('attributes', 'max_impedance_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Maximum active power drawn by constant impedance load.'),
    ('attributes', 'max_impedance_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Maximum active power drawn by constant impedance load.'),
    ('attributes', 'max_impedance_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Maximum reactive power drawn by constant impedance load.'),
    ('attributes', 'max_impedance_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Maximum reactive power drawn by constant impedance load.'),
    ('attributes', 'max_reactive_power', 'ReactivePower', 'MVAr', NULL, NULL, NULL, NULL, NULL, NULL, 'Maximum reactive power demand'),
    ('attributes', 'min_compounding_voltage', 'Voltage', 'kV', NULL, NULL, NULL, NULL, NULL, NULL, 'Minimum compounded voltage. Only used in constant gamma operation (gamma_min = gamma_max), and the AC transformer is used to control the DC voltage.'),
    ('attributes', 'minimum_time', 'OperationalDuration', 'min', NULL, NULL, NULL, NULL, NULL, NULL, 'Minimum operating time for the specific mode.'),
    ('attributes', 'new_construction_year', 'Dimensionless', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'The year in which the new demand requirement will be installed. Should only be used for new demand requirements.'),
    ('attributes', 'new_demand_mw', 'ActivePower', 'MW', NULL, NULL, NULL, NULL, NULL, NULL, 'The value of the peak demand to be used for new DemandRequirements.'),
    ('attributes', 'peak_active_power', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Peak active power in the zone.'),
    ('attributes', 'peak_active_power', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Peak active power in the zone.'),
    ('attributes', 'peak_demand_mw', 'ActivePower', 'MW', NULL, NULL, NULL, NULL, NULL, NULL, 'Demand requirement peak demand'),
    ('attributes', 'peak_reactive_power', 'ReactivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Peak reactive power in the zone.'),
    ('attributes', 'peak_reactive_power', 'ReactivePower', 'MVAr', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Peak reactive power in the zone.'),
    ('attributes', 'power_factor_setpoint_from', 'PowerFactor', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Power-factor setpoint of the `from` bus converter, used when `ac_control_from` is `AC_REACTIVE_POWER`; `null` otherwise.'),
    ('attributes', 'power_factor_setpoint_to', 'PowerFactor', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Power-factor setpoint of the `to` bus converter, used when `ac_control_to` is `AC_REACTIVE_POWER`; `null` otherwise.'),
    ('attributes', 'power_factor_weighting_fraction_from', 'Fraction', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Power weighting factor fraction used in reducing the active power order and either the reactive power order when the converter rating is violated. When is 0.0, only the active power is reduced; when is 1.0, only the reactive power is reduced; otherwise, a weighted reduction of both active and reactive power is applied.'),
    ('attributes', 'power_factor_weighting_fraction_to', 'Fraction', '1', NULL, NULL, NULL, NULL, NULL, NULL, 'Power weighting factor fraction used in reducing the active power order and either the reactive power order when the converter rating is violated. When is 0.0, only the active power is reduced; when is 1.0, only the reactive power is reduced; otherwise, a weighted reduction of both active and reactive power is applied.'),
    ('attributes', 'power_trajectory', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Power trajectory the unit will take during the start-up and shut-down ramp process.'),
    ('attributes', 'power_trajectory', 'ActivePower', 'MW', 'power_units', 'NATURAL_UNITS', NULL, NULL, NULL, NULL, 'Power trajectory the unit will take during the start-up and shut-down ramp process.'),
    ('attributes', 'power_transfer_setpoint', 'ActivePower', 'pu', 'power_units', 'COMPONENT_BASE', NULL, NULL, NULL, NULL, 'Scheduled power transfer, used when `control_mode` is `POWER`; `null` otherwise. Must not be specified in per-unit. A positive value is the power consumed at the rectifier bus; a negative value is the power delivered at the inverter bus (its absolute value is the generated power at the inverter bus).'),
