INSERT INTO unit_basis_rules (quantity_kind, base_expression, description) VALUES
    ('ActivePower', 'base_power', 'Per-unit active power: divide by the row''s base power'),
    ('ActivePowerChangeRate', 'base_power', 'Per-unit active power ramp rate: divide by the row''s base power; the /min in pu/min is a per-minute rate, not a separate time base'),
    ('ApparentPower', 'base_power', 'Per-unit apparent power: divide by the row''s base power'),
    ('Conductance', 'base_power/base_voltage^2', 'Per-unit conductance: base admittance is base_power/base_voltage^2'),
    ('Reactance', 'base_voltage^2/base_power', 'Per-unit reactance: base impedance is base_voltage^2/base_power'),
    ('ReactivePower', 'base_power', 'Per-unit reactive power: divide by the row''s base power'),
    ('Resistance', 'base_voltage^2/base_power', 'Per-unit resistance: base impedance is base_voltage^2/base_power'),
    ('Susceptance', 'base_power/base_voltage^2', 'Per-unit susceptance: base admittance is base_power/base_voltage^2'),
    ('Voltage', 'base_voltage', 'Per-unit voltage: divide by the row''s base voltage');
